"""``protocol/`` is generated by ``scripts/export_protocol.py`` and must be up to date (WP8)."""
import importlib.util
import json
import pathlib
import unittest

from engine.events import EVENT_TYPES, parse_event

ROOT = pathlib.Path(__file__).resolve().parents[3]


def _exporter():  # type: ignore[no-untyped-def]
    spec = importlib.util.spec_from_file_location("export_protocol", ROOT / "scripts" / "export_protocol.py")
    assert spec is not None and spec.loader is not None
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


class ProtocolExportTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        cls.mod = _exporter()
        cls.files = cls.mod.build()

    def test_up_to_date(self) -> None:
        self.assertEqual(self.mod.stale(self.files), [],
                         "protocol/ is stale: run python3 scripts/export_protocol.py")

    def test_codes(self) -> None:
        c = json.loads(self.files["codes.json"])
        self.assertIn("build.distance_rule", c["errors"])
        self.assertIn("movement.unreachable", c["errors"])
        self.assertTrue(all("." in code and " " not in code for code in c["errors"]))
        self.assertEqual(c["events"], sorted(EVENT_TYPES))
        self.assertEqual(c["reasons"]["construction_cancelled"], ["builder_left", "cancelled", "conflict"])

    def test_owner_fixtures_parse_as_events(self) -> None:
        ev = json.loads(self.files["fixtures/events_seat0.json"])["events"]
        kinds = {d["k"] for d in ev}
        # the fixture game covers every event kind for a seated player
        self.assertEqual(kinds, set(EVENT_TYPES))
        for d in ev:
            if not any(k.endswith("_count") for k in d):   # unredacted: public or seat 0's own
                self.assertEqual(parse_event(d).to_dict(), d)

    def test_spectator_fixture_redacted(self) -> None:
        for d in json.loads(self.files["fixtures/events_spectator.json"])["events"]:
            self.assertNotEqual(d["k"], "buildable")
            for f in ("hand", "lost", "gained", "materials"):
                self.assertNotIn(f, d)
        st = json.loads(self.files["fixtures/state_spectator.json"])["state"]
        self.assertTrue(all("hand" not in p for p in st["players"]))


if __name__ == "__main__":
    unittest.main()
